  def test_every_added_operation_hits_its_route
    OPERATIONS.each do |verb, path, body, idem, call|
      http = Atlas::Test::StubRequester.new
      client = Atlas::Client.new("sk_test_123", http: http)
      http.enqueue(body: { "ok" => true })
      call.call(client)

      req = http.last
      assert_equal verb, req.method, path
      assert_equal "https://api.atlasauth.net#{path}", req.url
      if body.nil?
        assert_nil req.body, "#{verb} #{path} should send no body"
      else
        assert_equal body, JSON.parse(req.body), "#{verb} #{path} body"
        assert_equal "application/json", req.headers["content-type"]
      end
      if idem
        assert_equal "idem_1", req.headers["idempotency-key"], "#{verb} #{path} idempotency"
      else
        refute req.headers.key?("idempotency-key")
      end
    end
    assert_equal 235, OPERATIONS.length
  end
